}

// bucketStart is the first day of the bucket that holds day.
func bucketStart(day time.Time, group string) time.Time {
	switch group {
	case "week":
		return day.AddDate(0, 0, -(int(day.Weekday())+6)%7)
	case "month":
		return time.Date(day.Year(), day.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return day
}

// nextBucket is the first day of the bucket after the one starting on start.
func nextBucket(start time.Time, group string) time.Time {
	switch group {
	case "week":
		return start.AddDate(0, 0, 7)
	case "month":
		return start.AddDate(0, 1, 0)
	}
	return start.AddDate(0, 0, 1)
}

// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Report is the revenue of an organization per bucket of days.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    string   `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Bucket is the revenue of one day, week or month, named by its first day (YYYY-MM-DD).
type Bucket struct {
	Start    string                 `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                    `json:"payments"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	loc, start, last, err := span(st, orgID, from, to)
	if err != nil {
		return nil, err
	}
	return dayRevenue(st, orgID, loc, start, last), nil
}

// RevenueReport adds up the organization's succeeded payments per bucket from the day from to the day to (YYYY-MM-DD,
// both included), in the organization's time zone. group is "day" (the default), "week" (starting on Monday) or "month".
// Every bucket from the one holding from to the one holding to is in the report, in order, also those without payments.
func RevenueReport(st *store.Store, orgID, from, to, group string) (Report, error) {
	if group == "" {
		group = "day"
	}
	loc, start, last, err := span(st, orgID, from, to)
	if err != nil {
		return Report{}, err
	}
	if group != "day" && group != "week" && group != "month" {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	rep := Report{TimeZone: loc.String(), Group: group, Buckets: []Bucket{}}
	index := map[string]int{}
	last0 := bucketStart(last, group)
	for b := bucketStart(start, group); !b.After(last0); b = nextBucket(b, group) {
		index[b.Format(time.DateOnly)] = len(rep.Buckets)
		rep.Buckets = append(rep.Buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, d := range dayRevenue(st, orgID, loc, start, last) {
		day, _ := time.Parse(time.DateOnly, d.Date)
		b := &rep.Buckets[index[bucketStart(day, group).Format(time.DateOnly)]]
		b.Amounts[d.Currency] += d.Amount
		b.Payments += d.Payments
	}
	return rep, nil
}

// span checks the range and returns the organization's time zone with the days from and to as UTC midnights (days are
// calendar dates, so only their dates matter).
func span(st *store.Store, orgID, from, to string) (*time.Location, time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return nil, time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return nil, time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return nil, time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return nil, time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	loc := time.UTC
	if org, ok := st.Org(orgID); ok {
		if l, err := time.LoadLocation(org.TimeZone); err == nil {
			loc = l
		}
	}
	return loc, start, last, nil
}

// dayRevenue sums the succeeded payments made from the day start to the day last (both included, in loc) per day and
// currency, in date order.
func dayRevenue(st *store.Store, orgID string, loc *time.Location, start, last time.Time) []DayRevenue {
	from, to := start.Format(time.DateOnly), last.Format(time.DateOnly)
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		day := p.CreatedAt.In(loc).Format(time.DateOnly)
		if day < from || day > to {
			continue
		}
		k := key{day, p.Currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: day, Currency: p.Currency}
			sums[k] = d
		}
		d.Amount += p.Amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out
}

// bucketStart is the first day of the bucket that holds day.
func bucketStart(day time.Time, group string) time.Time {
	switch group {
	case "week":
		return day.AddDate(0, 0, -(int(day.Weekday())+6)%7)
	case "month":
		return time.Date(day.Year(), day.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return day
}

// nextBucket is the first day of the bucket after the one starting on start.
func nextBucket(start time.Time, group string) time.Time {
	switch group {
	case "week":
		return start.AddDate(0, 0, 7)
	case "month":
		return start.AddDate(0, 1, 0)
	}
	return start.AddDate(0, 0, 1)
}

