	pay("2026-03-02 21:00", 1000, money.USD, ok) // 02:00 UTC the next day, still March 2 in New York
	pay("2026-03-08 23:59", 200, money.USD, ok)  // the day daylight saving time starts: 23 hours long
	pay("2026-03-09 00:01", 300, money.USD, ok)
	pay("2026-03-09 12:00", 700, money.EUR, ok)
	pay("2026-03-09 13:00", 999, money.USD, store.PaymentFailed)
	pay("2026-03-16 12:00", 400, money.USD, ok)
	pay("2026-11-01 23:30", 50, money.USD, ok) // the day daylight saving time ends: 25 hours long

	day := func(d string, amounts map[money.Currency]int64, payments int) Bucket {
		return Bucket{Start: d, Amounts: amounts, Payments: payments}
	}
	cases := []struct {
		name            string
		from, to, group string
		want            Report
	}{
		{"days", "2026-03-07", "2026-03-10", "", Report{TimeZone: "America/New_York", Group: "day", Buckets: []Bucket{
			day("2026-03-07", map[money.Currency]int64{}, 0),
			day("2026-03-08", map[money.Currency]int64{money.USD: 200}, 1),
			day("2026-03-09", map[money.Currency]int64{money.USD: 300, money.EUR: 700}, 2),
			day("2026-03-10", map[money.Currency]int64{}, 0),
		}}},
		{"weeks start on Monday", "2026-03-04", "2026-03-16", "week", Report{TimeZone: "America/New_York", Group: "week", Buckets: []Bucket{
			day("2026-03-02", map[money.Currency]int64{money.USD: 200}, 1),
			day("2026-03-09", map[money.Currency]int64{money.USD: 300, money.EUR: 700}, 2),
			day("2026-03-16", map[money.Currency]int64{money.USD: 400}, 1),
		}}},
		{"months", "2026-02-10", "2026-04-02", "month", Report{TimeZone: "America/New_York", Group: "month", Buckets: []Bucket{
			day("2026-02-01", map[money.Currency]int64{}, 0),
			day("2026-03-01", map[money.Currency]int64{money.USD: 1900, money.EUR: 700}, 5),
			day("2026-04-01", map[money.Currency]int64{}, 0),
		}}},
		{"the day the clocks go back", "2026-11-01", "2026-11-01", "day", Report{TimeZone: "America/New_York", Group: "day", Buckets: []Bucket{
			day("2026-11-01", map[money.Currency]int64{money.USD: 50}, 1),
		}}},
	}
	for _, c := range cases {
		got, err := RevenueReport(st, o.ID, c.from, c.to, c.group)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("%s = %+v, want %+v", c.name, got, c.want)
		}
	}

	if _, err := RevenueReport(st, o.ID, "2026-03-01", "2026-03-05", "year"); !errors.Is(err, ErrInvalidGroup) {
		t.Errorf("group year: %v, want %v", err, ErrInvalidGroup)
	}
	if _, err := RevenueReport(st, o.ID, "2026-03-05", "2026-03-01", "day"); !errors.Is(err, ErrInvalidRange) {
		t.Errorf("to before from: %v, want %v", err, ErrInvalidRange)
	}
	if _, err := RevenueReport(st, o.ID, "03-01", "2026-03-05", "day"); !errors.Is(err, ErrInvalidDate) {
		t.Errorf("bad from: %v, want %v", err, ErrInvalidDate)
	}

	got, err := Revenue(st, o.ID, "2026-03-02", "2026-03-02")
	if err != nil || len(got) != 1 || got[0] != (DayRevenue{Date: "2026-03-02", Currency: money.USD, Amount: 1000, Payments: 1}) {
		t.Fatalf("Revenue in the organization's time zone = %+v, %v", got, err)
	}
}
